let objectUrls=new Map();
function lang(){return localStorage.getItem(LANG_KEY)||'ar'}
function tr(k){return (T[lang()]&&T[lang()][k])||T.ar[k]||k}
function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function setLang(l,save=true){
  if(!T[l]) l='ar';
  if(save) localStorage.setItem(LANG_KEY,l);
  document.documentElement.lang=l;
  document.documentElement.dir=l==='ar'?'rtl':'ltr';
  document.title=tr('title');
  document.querySelectorAll('[data-i18n]').forEach(el=>{el.innerHTML=tr(el.dataset.i18n)});
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=tr(el.dataset.i18nPlaceholder));
  document.querySelectorAll('[data-i18n-title]').forEach(el=>el.title=tr(el.dataset.i18nTitle));
  document.querySelectorAll('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',tr(el.dataset.i18nAria)));
  document.querySelectorAll('[data-i18n-value]').forEach(el=>el.value=tr(el.dataset.i18nValue));
  const sel=document.getElementById('languageSelect');
  if(sel) sel.value=l;
  updateLanguageOptions();
  updateFormLabels();
  if(typeof renderPriceTicker==='function') renderPriceTicker();
  if(document.body?.dataset.page==='home') applyHomeLanguage(l);
}
function updateLanguageOptions(){
  const sel=document.getElementById('languageSelect');
  if(!sel)return;
  sel.innerHTML='<option value="ar">العربية</option><option value="fr">Français</option><option value="en">English</option>';
  sel.value=lang();
}
function addLanguageControl(){
  const nav=document.querySelector('.nav');
  if(!nav)return;
  let sel=document.getElementById('languageSelect');
  if(!sel){
    sel=document.createElement('select');
    sel.id='languageSelect';
    sel.className='language-select';
    const anchor=nav.querySelector('.btn');
    nav.insertBefore(sel,anchor||null);
  }
  sel.setAttribute('aria-label',tr('language'));
  sel.onchange=()=>{ localStorage.setItem(LANG_KEY,sel.value); setLang(sel.value,true); };
  updateLanguageOptions();
}
function applyI18n(){addLanguageControl();setLang(lang(),false)}

