function listings(){try{const x=JSON.parse(localStorage.getItem(KEY));const user=Array.isArray(x)?x.filter(z=>!z.demo):[];return user}catch{return demo}}
function saveListings(a){localStorage.setItem(KEY,JSON.stringify((Array.isArray(a)?a:[]).filter(z=>!z?.demo)))}
function removeListing(id){
  const key=String(id);
  let raw=[];
  try{raw=JSON.parse(localStorage.getItem(KEY)||'[]')}catch{raw=[]}
  const before=raw.length;
  const kept=raw.filter(z=>String(z?.id)!==key);
  localStorage.setItem(KEY,JSON.stringify(kept.filter(z=>!z?.demo)));
  return before-kept.length;
}
function updateListing(id,patch){const arr=listings();const i=arr.findIndex(z=>String(z.id)===String(id));if(i<0)return false;arr[i]={...arr[i],...patch};saveListings(arr);return true}
function sponsoredAds(){try{const x=JSON.parse(localStorage.getItem(SPONSORED_KEY)||'[]');return Array.isArray(x)?x.filter(z=>z&&z.active!==false):[]}catch{return []}}
function saveSponsored(a){localStorage.setItem(SPONSORED_KEY,JSON.stringify(Array.isArray(a)?a:[]))}
function requests(){try{const x=JSON.parse(localStorage.getItem(REQUESTS_KEY)||'[]');return Array.isArray(x)?x:[]}catch{return []}}
function saveRequests(a){localStorage.setItem(REQUESTS_KEY,JSON.stringify(Array.isArray(a)?a:[]))}
function publicListings(){return listings().filter(x=>x.status!=='pending_payment'&&x.status!=='hidden').slice().sort((a,b)=>{const sa=a.sponsored?1:0,sb=b.sponsored?1:0;return sb-sa||new Date(b.createdAt)-new Date(a.createdAt)})}
function ownerToken(){let x=localStorage.getItem(OWNER_KEY);if(!x){x=crypto.randomUUID?crypto.randomUUID():'owner_'+Date.now()+'_'+Math.random().toString(36).slice(2);localStorage.setItem(OWNER_KEY,x)}return x}
function wa(n){let x=String(n||'').replace(/\D/g,'');if(x.startsWith('0'))x='212'+x.slice(1);if(!x.startsWith('212'))x='212'+x;return 'https://wa.me/'+x}
function phoneHref(n){return 'tel:'+String(n||'').replace(/\s/g,'')}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(MEDIA_STORE))r.result.createObjectStore(MEDIA_STORE,{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function putMedia(file){const db=await openDB();const id='media_'+Date.now()+'_'+Math.random().toString(36).slice(2,9);await new Promise((resolve,reject)=>{const tx=db.transaction(MEDIA_STORE,'readwrite');tx.objectStore(MEDIA_STORE).put({id,blob:file,type:file.type,name:file.name,size:file.size});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});return {id,type:file.type.startsWith('video/')?'video':'image',name:file.name,size:file.size}}
async function getMedia(id){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(MEDIA_STORE,'readonly');const r=tx.objectStore(MEDIA_STORE).get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}
async function deleteMedia(id){try{const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction(MEDIA_STORE,'readwrite');tx.objectStore(MEDIA_STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}catch{}}
async function mediaUrl(m){if(!m)return null;if(m.url)return m.url;if(!m.id)return null;if(objectUrls.has(m.id))return objectUrls.get(m.id);const item=await getMedia(m.id);if(!item)return null;const u=URL.createObjectURL(item.blob);objectUrls.set(m.id,u);return u}
async function firstMedia(x){const m=(x.media&&x.media[0])||{url:x.image||'',type:'image'};return {meta:m,url:await mediaUrl(m)}}
function kindLabel(k){return k==='بيع'?tr('forSale'):tr('wanted')}
function categoryLabel(c){return c==='زيت الزيتون'?tr('oil'):tr('equipment')}
async function cardHtml(x){const fm=await firstMedia(x);const isVideo=fm.meta.type==='video';const sponsored=x.sponsored===true;return `<article class="card ${sponsored?'sponsored-card':''}"><a href="listing.html?id=${encodeURIComponent(x.id)}"><div class="card-image">${isVideo?`<video src="${esc(fm.url)}" muted playsinline preload="metadata"></video>`:`<img src="${esc(fm.url||'')}" alt="${esc(x.title)}" loading="lazy">`}<span class="badge ${sponsored?'sponsored-badge':x.kind==='بيع'?'sale':'buy'}">${sponsored?esc(tr('sponsored')):esc(kindLabel(x.kind))}</span>${(x.media||[]).length>1?`<span class="media-count">▧ ${(x.media||[]).length}</span>`:''}</div><div class="card-body">${sponsored?`<div class="sponsor-name">${esc(x.advertiser||'')}</div>`:''}<h3>${esc(x.title)}</h3><div class="price">${esc(x.price||tr('priceBudget'))}</div><div class="meta"><span>📍 ${esc(x.location||'')}</span><span>${sponsored?'✦':x.category==='زيت الزيتون'?'🫒':'⚙️'} ${esc(sponsored?tr('sponsored'):categoryLabel(x.category))}</span></div><div class="card-footer"><small>${esc(x.quantity||'')} ${x.quantity?'— ':''}${esc(x.condition||'')}</small><span class="link">${esc(tr('details'))} ←</span></div></div></a></article>`}
async function getById(id){return listings().find(x=>x.id===id)||sponsoredAds().find(x=>x.id===id)}
async function renderGrid(el,arr){if(!arr.length){el.innerHTML=`<div class="empty" style="grid-column:1/-1"><b>${esc(tr('noResults'))}</b>${esc(tr('changeSearch'))}</div>`;return}el.innerHTML=await Promise.all(arr.map(cardHtml)).then(x=>x.join(''))}
function filterData(){const c=document.getElementById('cat')?.value||'الكل',k=document.getElementById('kind')?.value||'الكل',q=(document.getElementById('q')?.value||'').trim().toLowerCase(),loc=(document.getElementById('locationFilter')?.value||'').trim().toLowerCase(),sort=document.getElementById('sort')?.value||'latest';let a=publicListings().filter(x=>x.sponsored||((c==='الكل'||x.category===c)&&(k==='الكل'||x.kind===k)&&(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!loc||String(x.location||'').toLowerCase().includes(loc)||String(x.region||'').toLowerCase().includes(loc))));if(sort==='oldest')a=a.reverse();return a}
async function renderSponsored(el){if(!el)return;const ads=sponsoredAds();el.innerHTML=ads.length?await Promise.all(ads.map(cardHtml)).then(x=>x.join('')):'';el.closest('.sponsored-section')?.classList.toggle('hidden',!ads.length)}
const PRICE_KEY='souk_market_prices_v1';
const DEFAULT_PRICES={es:'3.433',it:'4.394',eu:'3.619',gr:'3.705',virgin:'3.231',lamp:'3.060',date:'2026-10-04',source:'Olea Price — مؤشرات مرجعية يومية'};
function marketPrices(){try{return {...DEFAULT_PRICES,...JSON.parse(localStorage.getItem(PRICE_KEY)||'{}')}}catch{return DEFAULT_PRICES}}
function tickerItems(){const p=marketPrices(),l=lang();if(l==='en')return [['Spain EVOO',p.es,'€/kg'],['Italy EVOO',p.it,'€/kg'],['EU EVOO',p.eu,'€/kg'],['Greece EVOO',p.gr,'€/kg'],['Spain Virgin',p.virgin,'€/kg'],['Spain Lampante',p.lamp,'€/kg']];if(l==='fr')return [['Espagne AOVE',p.es,'€/kg'],['Italie AOVE',p.it,'€/kg'],['UE AOVE',p.eu,'€/kg'],['Grèce AOVE',p.gr,'€/kg'],['Espagne vierge',p.virgin,'€/kg'],['Espagne lampante',p.lamp,'€/kg']];return [['إسبانيا — بكر ممتاز',p.es,'يورو/كغ'],['إيطاليا — بكر ممتاز',p.it,'يورو/كغ'],['الاتحاد الأوروبي — بكر ممتاز',p.eu,'يورو/كغ'],['اليونان — بكر ممتاز',p.gr,'يورو/كغ'],['إسبانيا — بكر عادي',p.virgin,'يورو/كغ'],['إسبانيا — لامبانتي',p.lamp,'يورو/كغ']]}
function renderPriceTicker(){const el=document.getElementById('priceTicker');if(!el)return;const p=marketPrices(),items=tickerItems(),html=items.concat(items).map(([n,v,u])=>`<span class="ticker-item"><b>${esc(n)}</b><strong>${esc(v)}</strong><small>${esc(u)}</small></span>`).join('');el.innerHTML=`<div class="ticker-marquee">${html}</div>`;const d=document.getElementById('tickerUpdated');if(d)d.textContent=(lang()==='en'?'Updated: ':lang()==='fr'?'Mise à jour : ':'آخر تحديث: ')+(p.date||'—')}

async function initHome(){applyI18n();renderPriceTicker();await renderSponsored(document.getElementById('sponsoredGrid'));const grid=document.getElementById('homeGrid');if(grid)await renderGrid(grid,publicListings().filter(x=>!x.sponsored).slice(0,4));document.getElementById('searchGo')?.addEventListener('click',()=>{const q=document.getElementById('homeSearch').value.trim(),c=document.getElementById('homeCat').value;location.href='search.html?q='+encodeURIComponent(q)+'&cat='+encodeURIComponent(c)});document.getElementById('homeSearch')?.addEventListener('keydown',e=>{if(e.key==='Enter')document.getElementById('searchGo').click()})}
async function initSearch(){applyI18n();renderPriceTicker();syncSelectValues();const params=new URLSearchParams(location.search);if(params.get('q')!==null&&document.getElementById('q'))document.getElementById('q').value=params.get('q')||'';if(params.get('cat')&&document.getElementById('cat'))document.getElementById('cat').value=params.get('cat');const run=async()=>{await renderSponsored(document.getElementById('sponsoredGrid'));const a=filterData();await renderGrid(document.getElementById('grid'),a);const h=document.getElementById('resultsHint');if(h)h.textContent=`${a.length} إعلان متاح`};['cat','kind','q','locationFilter','sort'].forEach(id=>document.getElementById(id)?.addEventListener('input',run));await run()}
async function initDetail(){applyI18n();const x=await getById(new URLSearchParams(location.search).get('id'));const root=document.getElementById('detail');if(!x){root.innerHTML=`<div class="empty">${esc(tr('notFound'))}</div>`;return}const media=x.media||[{type:'image',url:x.image||''}];const resolved=await Promise.all(media.map(async m=>({m,url:await mediaUrl(m)})));const canEdit=!x.sponsored&&(!x.ownerToken||x.ownerToken===localStorage.getItem(OWNER_KEY));root.innerHTML=`<div class="detail-layout"><div class="gallery"><div class="gallery-main" id="galleryMain"><div class="gallery-stage" id="galleryStage"></div><button class="gallery-nav prev" id="galleryPrev" type="button" data-i18n-aria="previous">‹</button><button class="gallery-nav next" id="galleryNext" type="button" data-i18n-aria="next">›</button></div><div class="gallery-thumbs" id="galleryThumbs">${resolved.map((r,i)=>`<button class="thumb ${i===0?'active':''}" data-i="${i}" type="button">${r.m.type==='video'?`<span>▶</span>`:`<img src="${esc(r.url)}" alt="">`}</button>`).join('')}</div></div><div class="detail-box">${x.sponsored?`<span class="eyebrow sponsor-eyebrow">✦ ${esc(tr('sponsored'))}</span>`:`<span class="eyebrow">${esc(kindLabel(x.kind))} · ${esc(categoryLabel(x.category))}</span>`}<h1>${esc(x.title)}</h1><div class="detail-price">${esc(x.price||tr('priceBudget'))}</div><div class="meta"><span>📍 ${esc(x.location||'')}</span><span>🕒 ${esc(tr('postedRecently'))}</span></div><div class="specs">${x.sponsored?`<div class="spec"><small>المعلن</small><b>${esc(x.advertiser||'—')}</b></div>`:`<div class="spec"><small>${esc(tr('quantity'))}</small><b>${esc(x.quantity||'—')}</b></div><div class="spec"><small>${esc(tr('condition'))}</small><b>${esc(x.condition||'—')}</b></div><div class="spec"><small>${esc(tr(x.category==='زيت الزيتون'?'unitName':'sellerName'))}</small><b>${x.hideIdentity?'مخفي':esc(x.unit||'—')}</b></div>${x.category==='زيت الزيتون'&&x.kind==='بيع'?`<div class="spec"><small>${esc(tr('healthLicense'))}</small><b>${esc(x.onssa||'—')}</b></div>`:''}`}</div>${Array.isArray(x.offers)&&x.offers.length?`<section class="detail-offers"><h3>العروض المدرجة</h3><div class="detail-offers-grid">${x.offers.map((o,i)=>`<div class="detail-offer"><b>${esc(o.title||`العرض ${i+1}`)}</b>${o.quality?`<span>النوع: ${esc(o.quality)}</span>`:''}${o.price?`<strong>${esc(o.price)}</strong>`:''}${o.quantity?`<span>الكمية: ${esc(o.quantity)}</span>`:''}${o.condition?`<span>${esc(o.condition)}</span>`:''}</div>`).join('')}</div></section>`:''}<h3>${esc(tr('descriptionLabel'))}</h3><p class="detail-desc">${esc(x.description||'—')}</p><div class="contact">${x.phone&&!x.hidePhone?`<a class="btn primary" href="${phoneHref(x.phone)}">📞 ${esc(tr('contact'))}</a>`:''}${(x.whatsapp||x.phone)&&!x.hideWhatsapp?`<a class="btn whatsapp" target="_blank" rel="noopener" href="${wa(x.whatsapp||x.phone)}">${esc(tr('whatsappBtn'))}</a>`:''}${x.link?`<a class="btn gold" target="_blank" rel="noopener" href="${esc(x.link)}">زيارة الإعلان ↗</a>`:''}</div>${canEdit?`<div class="contact owner-actions"><a class="btn light" href="publish.html?edit=${encodeURIComponent(x.id)}">✎ ${esc(tr('edit'))}</a><button class="btn danger" id="deleteAd" type="button">⌫ ${esc(tr('delete'))}</button></div>`:''}<div class="notice" style="margin-top:14px">${esc(tr('communication'))}</div></div></div>`;setLang(lang(),false);const main=document.getElementById('galleryMain');const stage=document.getElementById('galleryStage');let current=0;const show=async i=>{current=(i+resolved.length)%resolved.length;const r=resolved[current];stage.innerHTML=r.m.type==='video'?`<video class="gallery-media" src="${esc(r.url)}" controls playsinline preload="metadata"></video>`:`<img class="gallery-media" src="${esc(r.url)}" alt="${esc(x.title)}">`;document.querySelectorAll('.thumb').forEach((b,j)=>b.classList.toggle('active',j===current));document.getElementById('galleryPrev')?.classList.toggle('hidden',resolved.length<2);document.getElementById('galleryNext')?.classList.toggle('hidden',resolved.length<2)};document.querySelectorAll('.thumb').forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.i))));document.getElementById('galleryPrev')?.addEventListener('click',()=>show(current-1));document.getElementById('galleryNext')?.addEventListener('click',()=>show(current+1));let sx=0,sy=0;main.addEventListener('touchstart',e=>{const t=e.changedTouches[0];sx=t.clientX;sy=t.clientY},{passive:true});main.addEventListener('touchend',e=>{const t=e.changedTouches[0],dx=t.clientX-sx,dy=t.clientY-sy;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy))show(current+(dx<0?1:-1))},{passive:true});await show(0);document.getElementById('deleteAd')?.addEventListener('click',async()=>{const btn=document.getElementById('deleteAd');if(btn?.disabled)return;if(!window.confirm(tr('confirmDelete')))return;btn.disabled=true;const removed=removeListing(x.id);for(const m of x.media||[])if(m.id)await deleteMedia(m.id);if(removed){alert(tr('deleted'));location.replace('search.html')}else{btn.disabled=false;alert('تعذر حذف الإعلان من التخزين المحلي. أعد فتح الصفحة وحاول مرة أخرى.')}})}
async function initPublish(){applyI18n();const form=document.getElementById('publishForm');const input=document.getElementById('mediaInput'),preview=document.getElementById('mediaPreview');let selected=[];let keptExisting=[];const editId=new URLSearchParams(location.search).get('edit');const editing=!!editId;const current=editing?await getById(editId):null;if(editing&&(!current||current.demo||(!adminAuthed()&&current.ownerToken!==localStorage.getItem(OWNER_KEY)))){alert(tr('notFound'));location.href='search.html';return}
 if(current){for(const [name,val] of Object.entries(current)){if(form.elements[name]&&name!=='media'){form.elements[name].value=val}}keptExisting=[...(current.media||[])];document.querySelector('[data-i18n="newAd"]')?.setAttribute('data-i18n','newAd');const titleEl=document.querySelector('[data-i18n="publishTitle"]');if(titleEl)titleEl.dataset.i18n='publishTitle';}
 document.addEventListener('click',e=>{if(e.target.closest('#lawLink')){e.preventDefault();document.getElementById('lawModal')?.classList.add('open')}if(e.target.closest('[data-close-law]'))document.getElementById('lawModal')?.classList.remove('open')});
 function renderSelected(){preview.innerHTML='';keptExisting.forEach((m,i)=>{const box=document.createElement('div');box.className='upload-item';mediaUrl(m).then(u=>{box.innerHTML=m.type==='video'?`<video src="${esc(u)}" muted playsinline controls></video>`:`<img src="${esc(u)}" alt="">`;const info=document.createElement('div');info.className='upload-item-info';info.textContent=m.name||tr('multipleMedia');const del=document.createElement('button');del.type='button';del.className='remove-media';del.textContent='×';del.addEventListener('click',async()=>{const old=keptExisting.splice(i,1)[0];if(old?.id)await deleteMedia(old.id);renderSelected()});box.append(info,del);});preview.appendChild(box)});selected.forEach((file,i)=>{const box=document.createElement('div');box.className='upload-item';const u=URL.createObjectURL(file);box.innerHTML=file.type.startsWith('video/')?`<video src="${u}" muted playsinline controls></video>`:`<img src="${u}" alt="">`;const info=document.createElement('div');info.className='upload-item-info';info.textContent=file.name;const del=document.createElement('button');del.type='button';del.className='remove-media';del.textContent='×';del.addEventListener('click',()=>{URL.revokeObjectURL(u);selected.splice(i,1);renderSelected()});box.append(info,del);preview.appendChild(box)})}
 input?.addEventListener('change',()=>{selected=[...selected,...[...input.files]];if(selected.length>8){selected=selected.slice(0,8);alert(tr('filesMax'))}input.value='';renderSelected()});
 form?.addEventListener('input',updateFormLabels);form?.addEventListener('change',updateFormLabels);
 form?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form);const x=Object.fromEntries(fd.entries());if(!fd.get('agree'))return alert(tr('agreeFirst'));if(x.category==='زيت الزيتون'&&x.kind==='بيع'&&x.onssa!=='نعم'&&x.onssa!=='حاصل')return alert(tr('oilLicenseRequired'));if(selected.length+keptExisting.length>8)return alert(tr('filesMax'));for(const f of selected){const max=f.type.startsWith('video/')?50*1024*1024:8*1024*1024;if(f.size>max)return alert(`${tr('fileTooLarge')} ${f.name}`)}const media=[...keptExisting];for(const f of selected)media.push(await putMedia(f));const mediaLinks=String(x.mediaLinks||'').split(/\n+/).map(v=>v.trim()).filter(Boolean).slice(0,8-media.length);for(const url of mediaLinks)media.push({type:/\.(mp4|webm|mov|m4v)(\?|$)/i.test(url)?'video':'image',url,name:'رابط وسائط'});x.media=media;try{x.offers=JSON.parse(x.offersJson||'[]')}catch{x.offers=[]}if(!Array.isArray(x.offers))x.offers=[];x.offers=x.offers.filter(o=>o&&Object.values(o).some(Boolean)).slice(0,12);x.createdAt=current?.createdAt||new Date().toISOString();x.ownerToken=current?.ownerToken||ownerToken();x.accountId=currentAccount?.()?.id||current?.accountId||null;x.publishPlan=fd.get('publishPlan')||'free';x.status=x.publishPlan==='premium'?'pending_payment':'published';x.paymentStatus=x.publishPlan==='premium'?'pending':'not_required';x.hidePhone=!!fd.get('hidePhone');x.hideWhatsapp=!!fd.get('hideWhatsapp');x.hideIdentity=!!fd.get('hideIdentity');if(editing)x.id=current.id;else x.id='ad_'+Date.now();delete x.agree;delete x.mediaInput;delete x.mediaLinks;delete x.offersJson;const arr=listings().filter(z=>!z.demo&&z.id!==x.id);saveListings([x,...arr]);if(x.publishPlan==='premium'){saveRequests([{id:'adpay_'+Date.now(),type:'premium_ad',adId:x.id,status:'pending',createdAt:new Date().toISOString(),accountId:x.accountId},...requests()]);alert('تم حفظ طلب الإشهار المميز. سيظهر الإعلان بعد تأكيد الإدارة والأداء.');location.href='advertise.html?ad='+encodeURIComponent(x.id)}else{alert(editing?tr('saved'):tr('published'));location.href='listing.html?id='+encodeURIComponent(x.id)}});renderSelected();updateFormLabels();if(editing){const h=document.querySelector('.form-title h1');if(h)h.textContent=tr('edit');const s=document.querySelector('.form-title .eyebrow');if(s)s.textContent=tr('edit');const b=form.querySelector('button[type=submit]');if(b)b.innerHTML=tr('update')}setLang(lang(),false)}
window.addEventListener('beforeunload',()=>objectUrls.forEach(u=>URL.revokeObjectURL(u)));

function adminAuthed(){return sessionStorage.getItem(ADMIN_SESSION_KEY)==='1'}
function renderAdminAds(){const el=document.getElementById('adminAds');if(!el)return;const arr=listings().slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));document.getElementById('kpiAds').textContent=arr.length;document.getElementById('kpiSponsored').textContent=sponsoredAds().length;if(!arr.length){el.innerHTML='<div class="empty">لا توجد إعلانات حالياً.</div>';return}el.innerHTML=arr.map(x=>`<div class="admin-row"><div class="admin-row-main"><span class="admin-chip">${esc(x.category||'')}</span><b>${esc(x.title||'')}</b><small>${esc(x.location||'')} · ${esc(x.phone||'')}</small></div><div class="admin-row-actions"><a class="btn light" href="listing.html?id=${encodeURIComponent(x.id)}">عرض</a><a class="btn light" href="publish.html?edit=${encodeURIComponent(x.id)}">تعديل</a><button class="btn danger admin-delete" data-id="${esc(x.id)}" type="button">حذف</button></div></div>`).join('');el.querySelectorAll('.admin-delete').forEach(btn=>btn.addEventListener('click',async()=>{if(!confirm('هل تريد حذف هذا الإعلان نهائياً؟'))return;const id=btn.dataset.id;const x=await getById(id);removeListing(id);for(const m of x?.media||[])if(m.id)await deleteMedia(m.id);renderAdminAds()}))}
function renderSponsoredAdmin(){const el=document.getElementById('sponsoredList');if(!el)return;const arr=sponsoredAds();el.innerHTML=arr.length?arr.map(x=>`<div class="admin-row sponsored-admin-row"><div class="admin-row-main"><span class="admin-chip gold-chip">✦ إشهار ${x.permanent?'دائم':''}</span><b>${esc(x.title)}</b><small>${esc(x.advertiser||'')} · ${x.featured?'يظهر أولاً':'عادي'}</small></div><div class="admin-row-actions"><button class="btn light sponsor-edit" data-id="${esc(x.id)}" type="button">تعديل</button><button class="btn danger sponsor-delete" data-id="${esc(x.id)}" type="button">حذف</button></div></div>`).join(''):'<div class="empty">لا توجد إعلانات إشهارية.</div>';el.querySelectorAll('.sponsor-delete').forEach(b=>b.addEventListener('click',()=>{if(!confirm('حذف هذا الإشهار؟'))return;saveSponsored(arr.filter(x=>x.id!==b.dataset.id));renderSponsoredAdmin()}));el.querySelectorAll('.sponsor-edit').forEach(b=>b.addEventListener('click',()=>{const x=arr.find(x=>x.id===b.dataset.id);if(!x)return;const f=document.getElementById('sponsoredForm');Object.entries(x).forEach(([k,v])=>{const e=f.elements[k];if(e){if(e.type==='checkbox')e.checked=!!v;else e.value=v}});f.scrollIntoView({behavior:'smooth',block:'center'})}))}
function renderAdminRequests(){const el=document.getElementById('adminRequests');if(!el)return;const arr=requests();document.getElementById('kpiRequests').textContent=arr.filter(x=>!x.read).length;if(!arr.length){el.innerHTML='<div class="empty">لا توجد طلبات واردة.</div>';return}el.innerHTML=arr.map(x=>`<div class="admin-row request-row ${x.read?'read':''}"><div class="admin-row-main"><span class="admin-chip">${esc(x.type)}</span><b>${esc(x.subject)}</b><small>${esc(x.name)} · ${esc(x.phone)} · ${new Date(x.createdAt).toLocaleString('ar-MA')}</small><p>${esc(x.message)}</p></div><div class="admin-row-actions">${x.read?'':'<button class="btn light request-read" data-id="'+esc(x.id)+'" type="button">تمت القراءة</button>'}<button class="btn danger request-delete" data-id="${esc(x.id)}" type="button">حذف</button></div></div>`).join('');el.querySelectorAll('.request-read').forEach(b=>b.addEventListener('click',()=>{const a=requests();const x=a.find(x=>x.id===b.dataset.id);if(x)x.read=true;saveRequests(a);renderAdminRequests()}));el.querySelectorAll('.request-delete').forEach(b=>b.addEventListener('click',()=>{if(!confirm('حذف الطلب؟'))return;saveRequests(requests().filter(x=>x.id!==b.dataset.id));renderAdminRequests()}))}
function initAdmin(){applyI18n();const login=document.getElementById('adminLogin'),panel=document.getElementById('adminPanel');const open=()=>{login?.classList.add('hidden');panel?.classList.remove('hidden');renderAdminAds();renderSponsoredAdmin();renderAdminRequests();renderAdminPrices()};if(adminAuthed())open();const submitLogin=()=>{const value=String(document.getElementById('adminPin')?.value||'').trim();if(value===ADMIN_PIN){sessionStorage.setItem(ADMIN_SESSION_KEY,'1');open();document.getElementById('adminPin').value='';history.replaceState({},'',location.pathname)}else{document.getElementById('adminPin')?.classList.add('invalid');alert('رمز الإدارة غير صحيح')}};document.getElementById('adminLoginForm')?.addEventListener('submit',e=>{e.preventDefault();submitLogin()});document.getElementById('adminLoginBtn')?.addEventListener('click',e=>{e.preventDefault();submitLogin()});document.getElementById('adminLogout')?.addEventListener('click',()=>{sessionStorage.removeItem(ADMIN_SESSION_KEY);location.href='admin.html'});document.querySelectorAll('.admin-tab').forEach(t=>t.addEventListener('click',()=>{document.querySelectorAll('.admin-tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('[data-section]').forEach(x=>x.classList.add('hidden'));t.classList.add('active');document.querySelector(`[data-section="${t.dataset.tab}"]`)?.classList.remove('hidden')}));document.getElementById('sponsoredForm')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),x=Object.fromEntries(fd.entries());const arr=sponsoredAds();const id=x.id||'sponsor_'+Date.now();const obj={id,advertiser:x.advertiser,title:x.title,description:x.description,image:x.image,link:x.link,phone:x.phone,whatsapp:x.whatsapp,permanent:f.elements.permanent.checked,featured:f.elements.featured.checked,active:true,sponsored:true,createdAt:arr.find(z=>z.id===id)?.createdAt||new Date().toISOString(),location:'المغرب',price:'',quantity:'',condition:'',media:x.image?[{type:'image',url:x.image}]:[]};saveSponsored([obj,...arr.filter(z=>z.id!==id)]);f.reset();f.elements.permanent.checked=true;f.elements.featured.checked=true;renderSponsoredAdmin();alert('تم حفظ الإعلان الإشهاري')});document.getElementById('sponsoredCancel')?.addEventListener('click',()=>document.getElementById('sponsoredForm').reset());document.getElementById('priceForm')?.addEventListener('submit',e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.currentTarget).entries());localStorage.setItem(PRICE_KEY,JSON.stringify({...marketPrices(),...x}));renderPriceTicker();alert('تم تحديث مؤشرات الأسعار')})}
function renderAdminPrices(){const f=document.getElementById('priceForm');if(!f)return;const p=marketPrices();Object.entries(p).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v||''})}

function initContact(){applyI18n();document.getElementById('contactAdminForm')?.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),x=Object.fromEntries(fd.entries());x.id='req_'+Date.now();x.createdAt=new Date().toISOString();x.read=false;saveRequests([x,...requests()]);e.currentTarget.reset();alert('تم إرسال طلبك إلى الإدارة.');location.href='index.html'})}


function initProfile(){const KEY_PROFILE='souk_professional_profile_v1';const form=document.getElementById('profileForm');let p={};try{p=JSON.parse(localStorage.getItem(KEY_PROFILE)||'{}')}catch{}if(form)Object.keys(p).forEach(k=>{if(form.elements[k]){if(form.elements[k].type==='checkbox')form.elements[k].checked=!!p[k];else form.elements[k].value=p[k]||''}});const slug=()=>String(p.username||p.unit||'profil').trim().toLowerCase().replace(/[^a-z0-9\u0600-\u06ff]+/g,'-').replace(/^-|-$/g,'')||'profil';const render=()=>{const ads=listings().filter(x=>!x.demo);document.getElementById('profileAds').textContent=ads.length;document.getElementById('profileSales').textContent=ads.filter(x=>x.kind==='بيع').length;document.getElementById('profileBuys').textContent=ads.filter(x=>x.kind==='شراء').length;document.getElementById('profileName').textContent=p.unit||'بياناتك المهنية';document.getElementById('profileSummary').textContent=p.bio||[p.activity,p.city,p.region].filter(Boolean).join(' · ')||'أنشئ ملفك ليظهر نشاطك وموقعك ومعلوماتك المهنية.';document.getElementById('profileList').innerHTML=ads.slice(0,6).map(x=>`<a class="profile-ad" href="listing.html?id=${encodeURIComponent(x.id)}"><b>${esc(x.title)}</b><small>${esc(x.location||'')} · ${esc(x.kind||'')}</small></a>`).join('')||'<div class="empty">لم تنشر أي إعلان بعد.</div>';const url='professional.html?u='+encodeURIComponent(slug());const a=document.getElementById('publicProfileBtn');if(a){a.href=url;a.classList.toggle('disabled',!p.unit)}const u=document.getElementById('publicProfileUrl');if(u)u.textContent=p.unit?url:'ستظهر بعد إنشاء ملفك'};form?.addEventListener('submit',e=>{e.preventDefault();p=Object.fromEntries(new FormData(form).entries());localStorage.setItem(KEY_PROFILE,JSON.stringify(p));render();alert('تم حفظ الملف المهني.')});render()}
async function initProfessional(){applyI18n();let p={};let profileOwnerId=null;const wanted=new URLSearchParams(location.search).get('u');const profiles=profileStore();if(wanted){const hit=Object.entries(profiles).find(([id,v])=>slugify(v.username||v.unit)===wanted);if(hit){profileOwnerId=hit[0];p=hit[1]}}if(!p.unit){const acc=currentAccount?.();if(acc){profileOwnerId=acc.id;p=accountProfile(acc)}}try{if(!p.unit)p=JSON.parse(localStorage.getItem('souk_professional_profile_v1')||'{}')}catch{}const root=document.getElementById('professional');if(!root)return;if(!p.unit){root.innerHTML='<div class="empty"><b>الملف المهني غير منشأ بعد</b><a class="btn primary" href="account.html">إنشاء الحساب والملف المهني</a></div>';return}const ads=listings().filter(x=>!x.demo&&x.status!=='pending_payment'&&(x.unit===p.unit&&(!profileOwnerId||!x.accountId||x.accountId===profileOwnerId)));root.innerHTML=`<section class="public-profile"><div class="public-profile-head"><div class="profile-avatar">${esc((p.unit||'م').slice(0,1))}</div><div><span class="eyebrow">ملف مهني</span><h1>${esc(p.unit)}</h1><p>${esc(p.bio||'')}</p><div class="meta"><span>📍 ${esc([p.city,p.region].filter(Boolean).join(' · '))}</span><span>🏷️ ${esc(p.activity||'')}</span></div></div></div>${p.oilQuality&&p.oilPrice?`<div class="public-oil-price"><div><small>زيت الزيتون المعروض</small><b>${esc(p.oilQuality)}</b></div><strong>${esc(p.oilPrice)}</strong><span>آخر تحديث: ${esc(p.oilPriceUpdated||'—')}</span></div>`:''}<div class="public-profile-grid"><div><h2>إعلانات ${esc(p.unit)}</h2><div id="publicAds" class="grid"></div></div><aside class="profile-card"><h3>التواصل</h3><p>يمكن لصاحب الملف إظهار أو إخفاء وسائل التواصل حسب الإعلانات.</p>${p.phone?`<a class="btn primary" href="${phoneHref(p.phone)}">📞 الاتصال</a>`:''}${p.whatsapp?`<a class="btn whatsapp" target="_blank" rel="noopener" href="${wa(p.whatsapp)}">◉ واتساب</a>`:''}<a class="btn light" href="oil-directory.html">دليل المعاصر والمسوقين</a></aside></div></section>`;await renderGrid(document.getElementById('publicAds'),ads)}
window.Souk={listings,saveListings,initHome,initSearch,initDetail,initPublish,initProfile,initProfessional,initAccount,initDirectory,setLang,applyI18n,initAdmin,initContact,renderPriceTicker};

/* V8 — account, public directory, global language/header, publishing plans */
const ACCOUNTS_KEY='souk_accounts_v2';
const CURRENT_ACCOUNT_KEY='souk_current_account_v2';
const PROFILE_KEY='souk_profiles_v2';
const PRICE_REMOTE='prices.json';

function allAccounts(){try{const x=JSON.parse(localStorage.getItem(ACCOUNTS_KEY)||'[]');return Array.isArray(x)?x:[]}catch{return[]}}
function saveAccounts(a){localStorage.setItem(ACCOUNTS_KEY,JSON.stringify(a))}
function currentAccount(){try{const id=localStorage.getItem(CURRENT_ACCOUNT_KEY);return allAccounts().find(x=>x.id===id)||null}catch{return null}}
function slugify(v){return String(v||'profil').trim().toLowerCase().replace(/[^a-z0-9\u0600-\u06ff]+/g,'-').replace(/^-|-$/g,'')||'profil'}
async function hashPassword(v){const data=new TextEncoder().encode(String(v));const hash=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function profileStore(){try{return JSON.parse(localStorage.getItem(PROFILE_KEY)||'{}')}catch{return{}}}
function saveProfileStore(x){localStorage.setItem(PROFILE_KEY,JSON.stringify(x||{}))}
function accountProfile(acc){const all=profileStore();return all[acc?.id]||{}}
function saveAccountProfile(acc,p){const all=profileStore();all[acc.id]=p;saveProfileStore(all)}
function isPaidPlan(){return document.querySelector('input[name="publishPlan"]:checked')?.value==='premium'}

const RULES_ACCEPT_KEY='souk_internal_rules_acceptance_v1';
function platformRulesAccepted(){return localStorage.getItem(RULES_ACCEPT_KEY)==='accepted'}
function mountPlatformGate(){
  if(document.body?.classList.contains('admin-page')||document.getElementById('platformGate'))return;
  if(platformRulesAccepted())return;
  const box=document.createElement('div');box.id='platformGate';box.className='platform-gate';box.innerHTML=`<div class="platform-gate-box" role="dialog" aria-modal="true" aria-labelledby="gateTitle"><div class="platform-gate-head"><img class="platform-gate-logo" src="logoSAM.png" alt="MAASSIR MARKET"><div><span class="eyebrow">سوق معاصر المغرب · MAASSIR MARKET</span><h2 id="gateTitle">الموافقة على القانون الداخلي</h2><p>يرجى قراءة القانون الداخلي والموافقة عليه قبل ولوج المنصة واستعمال خدماتها.</p></div></div><div class="law-content">${tr('lawBody')}</div><label class="gate-agree"><input id="platformGateAgree" type="checkbox"><span>أوافق على القانون الداخلي، وأقر بأنني مسؤول عن صحة معلومات إعلاني وعن معاملتي مع الطرف الآخر، وأن المنصة ليست طرفاً في المعاملة ولا تضمن إتمامها.</span></label><div class="gate-actions"><button id="platformGateEnter" class="btn primary" type="button" disabled>أوافق وأدخل إلى المنصة</button></div></div>`;
  document.body.appendChild(box);
  const check=box.querySelector('#platformGateAgree'),enter=box.querySelector('#platformGateEnter');
  check.addEventListener('change',()=>{enter.disabled=!check.checked});
  enter.addEventListener('click',()=>{if(!check.checked)return;localStorage.setItem(RULES_ACCEPT_KEY,'accepted');box.remove()});
}

function mountGlobalHeader(){
  if(document.body?.classList.contains('admin-page')) return;
  const nav=document.querySelector('.topbar .nav'); if(!nav||nav.dataset.v8Mounted==='1') return;
  nav.dataset.v8Mounted='1';
  nav.innerHTML=`<a class="brand brand-logo-only" href="index.html" aria-label="سوق معاصر المغرب — MAASSIR MARKET"><img src="logoSAM.png" alt="سوق معاصر المغرب — MAASSIR MARKET"></a>
  <nav class="navlinks global-links"><a id="gNavHome" href="index.html">الرئيسية</a><a id="gNavMarket" href="search.html">تصفح السوق</a><a id="gNavDirectory" href="oil-directory.html">المعاصر والمسوقون</a><a id="gNavProfile" href="profile.html">صفحتي المهنية</a></nav>
  <div class="global-actions"><select id="languageSelect" class="language-select" aria-label="اللغة"><option value="ar">العربية</option><option value="fr">Français</option><option value="en">English</option></select><a id="gAccount" class="btn light" href="account.html">حسابي</a><a id="gPublish" class="btn primary" href="publish.html">＋ نشر إعلان</a><button id="mobileMenuBtn" class="mobile-menu-btn" type="button" aria-expanded="false" aria-label="القائمة">☰</button></div>
  <div id="mobileMenu" class="mobile-menu"><a id="mHome" href="index.html">الرئيسية</a><a id="mMarket" href="search.html">تصفح السوق</a><a id="mDirectory" href="oil-directory.html">المعاصر والمسوقون</a><a id="mProfile" href="profile.html">صفحتي المهنية</a><a id="mAccount" href="account.html">حسابي</a><a id="mPublish" href="publish.html">＋ نشر إعلان</a></div>`;
  document.getElementById('languageSelect').onchange=e=>setLang(e.target.value,true);
  document.getElementById('mobileMenuBtn').onclick=()=>{const m=document.getElementById('mobileMenu'),b=document.getElementById('mobileMenuBtn');const open=m.classList.toggle('open');b.setAttribute('aria-expanded',String(open))};
  mountPlatformGate();
}
function applyGlobalChrome(l){
  const M={ar:{home:'الرئيسية',market:'تصفح السوق',directory:'المعاصرون والمسوقون',profile:'صفحتي المهنية',account:'حسابي',publish:'＋ نشر إعلان',menu:'القائمة'},fr:{home:'Accueil',market:'Marché',directory:'Moulins & vendeurs',profile:'Mon profil',account:'Mon compte',publish:'＋ Publier',menu:'Menu'},en:{home:'Home',market:'Browse market',directory:'Mills & sellers',profile:'My profile',account:'My account',publish:'＋ Post an ad',menu:'Menu'}}[l]||null;if(!M)return;const q=(id,t)=>{const e=document.getElementById(id);if(e)e.textContent=t};['gNavHome','mHome'].forEach(id=>q(id,M.home));['gNavMarket','mMarket'].forEach(id=>q(id,M.market));['gNavDirectory','mDirectory'].forEach(id=>q(id,M.directory));['gNavProfile','mProfile'].forEach(id=>q(id,M.profile));['gAccount','mAccount'].forEach(id=>q(id,M.account));['gPublish','mPublish'].forEach(id=>q(id,M.publish));const b=document.getElementById('mobileMenuBtn');if(b)b.setAttribute('aria-label',M.menu);}

/* wrap the existing setter so every page receives the same language/header */
const _setLangV7=setLang;
setLang=function(l,save=true){mountGlobalHeader();_setLangV7(l,save);applyGlobalChrome(l);if(document.body?.dataset.page==='home')applyHomeLanguage(l);if(document.body?.dataset.page==='home')renderPriceTicker();};

async function loadRemotePrices(){
  try{const r=await fetch(PRICE_REMOTE,{cache:'no-store'});if(!r.ok)throw new Error('price');const data=await r.json();if(data&&data.es){localStorage.setItem(PRICE_KEY,JSON.stringify({...marketPrices(),...data}));renderPriceTicker();}}catch{}
}

async function initAccount(){
  mountGlobalHeader(); applyI18n();
  const auth=document.getElementById('accountAuth'),dash=document.getElementById('accountDashboard');
  const render=()=>{const acc=currentAccount();if(acc){auth?.classList.add('hidden');dash?.classList.remove('hidden');const w=document.getElementById('accountWelcome');if(w)w.textContent=`مرحباً ${acc.name}`;const p=accountProfile(acc);const slug=p.username||p.unit||acc.name;const a=document.getElementById('accountPublicPage');if(a)a.href='professional.html?u='+encodeURIComponent(slugify(slug));}else{auth?.classList.remove('hidden');dash?.classList.add('hidden')}};
  document.querySelectorAll('[data-account-tab]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-account-tab]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const reg=btn.dataset.accountTab==='register';document.getElementById('registerForm')?.classList.toggle('hidden',!reg);document.getElementById('loginForm')?.classList.toggle('hidden',reg)}));
  document.getElementById('registerForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,x=Object.fromEntries(new FormData(f).entries());if(x.password!==x.password2)return alert('رمزا الدخول غير متطابقين.');const email=x.email.trim().toLowerCase();if(allAccounts().some(a=>a.email===email))return alert('هذا البريد مسجل من قبل.');const acc={id:'acc_'+Date.now()+'_'+Math.random().toString(36).slice(2,8),name:x.name.trim(),email,passwordHash:await hashPassword(x.password),createdAt:new Date().toISOString()};saveAccounts([...allAccounts(),acc]);localStorage.setItem(CURRENT_ACCOUNT_KEY,acc.id);saveAccountProfile(acc,{username:slugify(acc.name),unit:acc.name,activity:'',showInDirectory:false});render();alert('تم إنشاء الحساب. أكمل بيانات صفحتك المهنية.');location.href='profile.html'});
  document.getElementById('loginForm')?.addEventListener('submit',async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.currentTarget).entries()),acc=allAccounts().find(a=>a.email===x.email.trim().toLowerCase());if(!acc||acc.passwordHash!==await hashPassword(x.password)){const m=document.getElementById('authMessage');if(m)m.textContent='البريد الإلكتروني أو رمز الدخول غير صحيح.';return}localStorage.setItem(CURRENT_ACCOUNT_KEY,acc.id);render();});
  document.getElementById('logoutBtn')?.addEventListener('click',()=>{localStorage.removeItem(CURRENT_ACCOUNT_KEY);render()});render();
}

async function initDirectory(){
  mountGlobalHeader();applyI18n();
  const grid=document.getElementById('directoryGrid');const search=document.getElementById('directorySearch'),quality=document.getElementById('directoryQuality'),region=document.getElementById('directoryRegion');
  const build=()=>{const profiles=profileStore();let arr=Object.entries(profiles).map(([id,p])=>({...p,id})).filter(p=>p.showInDirectory&&p.unit&&p.oilQuality&&p.oilPrice);const regions=[...new Set(arr.map(p=>p.region).filter(Boolean))].sort();if(region)region.innerHTML='<option value="الكل">كل الجهات</option>'+regions.map(r=>`<option>${esc(r)}</option>`).join('');const q=(search?.value||'').toLowerCase(),qu=quality?.value||'الكل',rg=region?.value||'الكل';arr=arr.filter(p=>(!q||JSON.stringify(p).toLowerCase().includes(q))&&(qu==='الكل'||p.oilQuality===qu)&&(rg==='الكل'||p.region===rg));grid.innerHTML=arr.length?arr.map(p=>`<article class="directory-card"><div class="directory-card-top"><div class="directory-avatar">${esc((p.unit||'م').slice(0,1))}</div><div><h3>${esc(p.unit)}</h3><p>${esc([p.city,p.region].filter(Boolean).join(' · '))}</p></div></div><div class="oil-price-box"><small>${esc(p.oilQuality)}</small><strong>${esc(p.oilPrice)}</strong><span>آخر تحديث: ${esc(p.oilPriceUpdated||'—')}</span></div><p class="directory-bio">${esc(p.bio||'')}</p><a class="btn light" href="professional.html?u=${encodeURIComponent(slugify(p.username||p.unit))}">زيارة الصفحة</a></article>`).join(''):`<div class="empty" style="grid-column:1/-1"><b>لا توجد نتائج حالياً</b><span>يمكنك أن تكون من أوائل المعاصر والمسوقين في الدليل.</span></div>`};
  ['input','change'].forEach(ev=>{search?.addEventListener(ev,build);quality?.addEventListener(ev,build);region?.addEventListener(ev,build)});build();
}

/* Upgrade profile to account-linked professional data and oil price */
const _initProfileV7=initProfile;
initProfile=function(){
  mountGlobalHeader();applyI18n();
  const acc=currentAccount();const form=document.getElementById('profileForm');if(acc){const p=accountProfile(acc);if(form){form.elements.email.value=acc.email;form.elements.email.readOnly=true;Object.keys(p).forEach(k=>{if(form.elements[k])form.elements[k].value=p[k]||''});}};
  const KEY_PROFILE_LOCAL='souk_professional_profile_v1';let p=acc?accountProfile(acc):{};try{if(!Object.keys(p).length)p=JSON.parse(localStorage.getItem(KEY_PROFILE_LOCAL)||'{}')}catch{}
  const render=()=>{const ads=listings().filter(x=>!x.demo&&(!acc||!x.accountId||x.accountId===acc.id||x.ownerToken===localStorage.getItem(OWNER_KEY)));const el=id=>document.getElementById(id);if(el('profileAds'))el('profileAds').textContent=ads.length;if(el('profileSales'))el('profileSales').textContent=ads.filter(x=>x.kind==='بيع').length;if(el('profileBuys'))el('profileBuys').textContent=ads.filter(x=>x.kind==='شراء').length;if(el('profileName'))el('profileName').textContent=p.unit||acc?.name||'بياناتك المهنية';if(el('profileSummary'))el('profileSummary').textContent=p.bio||[p.activity,p.city,p.region].filter(Boolean).join(' · ')||'أنشئ ملفك ليظهر نشاطك وموقعك ومعلوماتك المهنية.';const slug=slugify(p.username||p.unit||acc?.name||'profil');const a=el('publicProfileBtn');if(a){a.href='professional.html?u='+encodeURIComponent(slug);a.classList.toggle('disabled',!p.unit)}if(el('publicProfileUrl'))el('publicProfileUrl').textContent=p.unit?'professional.html?u='+slug:'ستظهر بعد إنشاء ملفك';if(el('profileList'))el('profileList').innerHTML=ads.slice(0,6).map(x=>`<a class="profile-ad" href="listing.html?id=${encodeURIComponent(x.id)}"><b>${esc(x.title)}</b><small>${esc(x.location||'')} · ${esc(x.kind||'')}</small></a>`).join('')||'<div class="empty">لم تنشر أي إعلان بعد.</div>'};
  form?.addEventListener('submit',e=>{e.preventDefault();p=Object.fromEntries(new FormData(form).entries());p.showInDirectory=!!form.elements.showInDirectory?.checked;if(acc){saveAccountProfile(acc,p)}else{localStorage.setItem(KEY_PROFILE_LOCAL,JSON.stringify(p))}alert('تم حفظ الملف المهني.');render()});render();
}

const _initProfessionalV7=initProfessional;
initProfessional=async function(){mountGlobalHeader();await _initProfessionalV7();setLang(lang(),false)};

const _initHomeV7=initHome;
initHome=async function(){mountGlobalHeader();await _initHomeV7();loadRemotePrices()};
const _initSearchV7=initSearch;
initSearch=async function(){mountGlobalHeader();await _initSearchV7();loadRemotePrices()};

window.Souk={listings,saveListings,initHome,initSearch,initDetail,initPublish,initProfile,initProfessional,initAccount,initDirectory,setLang,applyI18n,initAdmin,initContact,renderPriceTicker};

setInterval(()=>{if(typeof loadRemotePrices==='function')loadRemotePrices()},6*60*60*1000);
